#================================#
# Load and format raw data

fiber.seq.df <- read.csv("./Revision_R_codes/008_fiber_seq/raw_data/Fiberseq_enhancer_scramble.tsv", sep = "\t")

fiber.seq.df <- fiber.seq.df %>% filter(name %in% c("No sv evidence", "wildtype", "∆R123", "∆R4", "∆R5")) %>% 
  mutate(name = case_when(name == "No sv evidence" ~ "no.sv",
                          name == "wildtype" ~ "WT",
                          name == "∆R123" ~ "R123",
                          name == "∆R4" ~ "R4",
                          name == "∆R5" ~ "R5")) 

#================================#
# Compute base composition of ROI in 50 nt bins

# Tile the region of interest into 50 nt bins
bin <- 50
roi.gr <- GRanges(seqnames = "chr14", ranges = IRanges(start = min(fiber.seq.df$start), end = max(fiber.seq.df$end)))
roi.tile.gr <- tile(roi.gr, width = bin) %>% unlist()

# Compute the numbers of A in each bin
genome <- BSgenome.Hsapiens.UCSC.hg38
roi.tile.gr$A_count <- letterFrequency(getSeq(genome, roi.tile.gr), "A")

#================================#
# Binarise m6A signal

fiber.seq.bin.df <- fiber.seq.df %>%
  mutate(score = ifelse(perc_m6A > 0, 1, 0)) %>% 
  dplyr::select(chr, start, end, fiber, name, score)

#================================#
# Compute the average m6A signal in each bin

# Define a function to compute the percentage of m6A in each 100 nt bins per fiber

get_fibre_perc <- function(fr, fiber.seq.bin.df, roi.tile.gr) {
  gr <- fiber.seq.bin.df %>%
    filter(fiber == fr) %>%
    dplyr::select(seqnames = chr, start, end, score) %>%
    GRanges()
  
  # Retain all roi.tile.gr intervals, filling absent overlaps with 0
  overlap.df <- mergeByOverlaps(roi.tile.gr, gr) %>%
    as.data.frame() %>%
    group_by(
      seqnames = roi.tile.gr.seqnames,
      start    = roi.tile.gr.start,
      end      = roi.tile.gr.end
    ) %>%
    summarise(A = first(A), m6A = sum(score), .groups = "drop")
  
  as.data.frame(roi.tile.gr) %>%
    dplyr::select(seqnames, start, end) %>%
    left_join(overlap.df, by = c("seqnames", "start", "end")) %>%
    mutate(
      A        = replace_na(A, 0),
      m6A      = replace_na(m6A, 0),
      perc.m6A = ifelse(A == 0, 0, (m6A / A) * 100),
      fiber    = fr
    ) %>%
    left_join(
      fiber.seq.bin.df %>% dplyr::select(fiber, name) %>% distinct(),
      by = "fiber"
    )
}

# Apply

fiber.seq.perc.df <- fiber.seq.bin.df %>%
  pull(fiber) %>%
  unique() %>%
  lapply(get_fibre_perc, fiber.seq.bin.df = fiber.seq.bin.df, roi.tile.gr = roi.tile.gr) %>%
  bind_rows()

# Save table
write.table(fiber.seq.perc.df, "./Revision_R_codes/008_fiber_seq/tsv/fiber_seq_perc_m6A.tsv", sep = "\t", row.names = F, quote = F)

# Aggregate fiber data
fiber.seq.perc.summary.df <- fiber.seq.perc.df %>%
  group_by(name, seqnames, start, end) %>% summarise(m6A = mean(m6A, na.rm = T), perc.m6A = mean(perc.m6A), .groups = "drop")

# Save table
write.table(fiber.seq.perc.summary.df, "./Revision_R_codes/008_fiber_seq/tsv/fiber_seq_perc_m6A.aggregated.tsv", sep = "\t", row.names = F, quote = F)

