# Generate and export bigwigs

# Retrieve hg38 chromosome lengths for seqinfo
hg38.seqinfo <- seqinfo(BSgenome.Hsapiens.UCSC.hg38)

# Export function
export_bigwig <- function(sample.name, fiber.seq.perc.summary.df, seqinfo, output.dir = ".") {
  
  gr <- fiber.seq.perc.summary.df %>%
    filter(name == sample.name) %>%
    dplyr::select(seqnames, start, end, score = perc.m6A) %>% GRanges()
  
  # Assign hg38 seqinfo and drop any non-standard chromosomes
  seqlevels(gr, pruning.mode = "coarse") <- seqlevels(seqinfo)
  seqinfo(gr) <- seqinfo
  
  out.path <- file.path(output.dir, paste0(sample.name, ".bw"))
  export(gr, con = out.path, format = "bigWig")
  
  message("Exported: ", out.path)
  invisible(out.path)
}

# Apply across all unique names
output.dir <- "./Revision_R_codes/008_fiber_seq/bw"
dir.create(output.dir, showWarnings = FALSE)

fiber.seq.perc.summary.df %>%
  pull(name) %>%
  unique() %>%
  lapply(
    export_bigwig,
    fiber.seq.perc.summary.df = fiber.seq.perc.summary.df,
    seqinfo           = hg38.seqinfo,
    output.dir        = output.dir
  )

