# Function to quantify signal over a domain

quantify_signal_func <- function(fiber.bw.path, domain_gr, sample) {
  fiber.bw <- import(fiber.bw.path, which = domain.gr)
  fiber.cpm.df <- mergeByOverlaps(fiber.bw, domain.gr) %>% as.data.frame() %>%
    dplyr::select(domain, score) %>% mutate(sample = sample)
}

# Compute

WT.fiber.df <- quantify_signal_func("./Revision_R_codes/008_fiber_seq/bw/WT.bw", domain.gr, "WT")
R123.fiber.df <- quantify_signal_func("./Revision_R_codes/008_fiber_seq/bw/R123.bw", domain.gr, "R123")
R4.fiber.df <- quantify_signal_func("./Revision_R_codes/008_fiber_seq/bw/R4.bw", domain.gr, "R4")
R5.fiber.df <- quantify_signal_func("./Revision_R_codes/008_fiber_seq/bw/R5.bw", domain.gr, "R5")

# Aggregate data
fiber.quant.df <- rbind(WT.fiber.df, R123.fiber.df, R4.fiber.df, R5.fiber.df) %>%
  mutate(sample = factor(sample, levels = c("WT", "R123", "R4", "R5")))

# Correct values for R4 and R5 domains
fiber.quant.df <- fiber.quant.df %>%
  mutate(score = case_when(
    sample == "R4" & domain == "R4_domain" ~ 0,
    sample == "R5" & domain == "R5_domain" ~ 0,
    TRUE ~ score
  ))

# Define a colour palette
sample_cols <- c(
  "WT"  = "#A7A8A9",
  "R123"  = "#55AC56",
  "R4"  = "#6B8EC9",
  "R5"  = "#A72A2B")

# Plot

fiber.quant.plot <- fiber.quant.df %>%
  ggplot(aes(x = sample, y = score, fill = sample)) +
  geom_boxplot(
    outliers = FALSE,
    width         = 0.6,
    linewidth     = 0.4,
    alpha         = 0.85
  ) +
  scale_fill_manual(values   = sample_cols) +
  scale_colour_manual(values = sample_cols) +
  scale_y_continuous(expand = expansion(mult = c(0.05, 0.25))) +
  facet_wrap(~ domain, scales = "free_y",
             nrow = 1,
             labeller = as_labeller(c(
               "R4_domain" = "R4 domain",
               "R5_domain" = "R5 domain"
             ))) +
  xlab(NULL) +
  ylab("% adenine methylated") +
  theme_bw() +
  theme(
    aspect.ratio     = 1.5,
    panel.grid       = element_blank(),
    strip.text       = element_text(size = 9, face = "bold"),
    axis.text.x      = element_text(angle = 45, hjust = 1, size = 9),
    axis.text.y      = element_text(size = 8),
    axis.title.y     = element_text(size = 9),
    legend.position  = "none"
  )

# Compute stats

stat.test <- fiber.quant.df %>%
  group_by(domain) %>%
  wilcox_test(score ~ sample, ref.group = "WT") %>%
  adjust_pvalue(method = "BH") %>%
  add_significance(
    p.col       = "p.adj",
    cutpoints   = c(0, 0.001, 0.01, 0.05, 1),
    symbols     = c("***", "**", "*", "ns")
  ) %>%
  add_xy_position(x = "sample", dodge = 0.8)

# Compute fold change of mean signal relative to WT
fc <- fiber.quant.df %>%
  group_by(domain, sample) %>%
  summarise(median_score = median(score, na.rm = TRUE), .groups = "drop") %>%
  group_by(domain) %>%
  mutate(FC_vs_WT = median_score / median_score[sample == "WT"],
         log2FC_vs_WT = log2(median_score / median_score[sample == "WT"]))
fc

# Export plot

